// borrow-optimized by shared parameters
pub fn divmod_integer(k: BigInt, l: &BigInt) -> (BigInt, BigInt) {
    if k.clone() == BigInt::ZERO {
        (BigInt::ZERO, BigInt::ZERO)
    } else if BigInt::ZERO < l.clone() {
        if BigInt::ZERO < k.clone() {
            std::convert::identity::<(BigInt, BigInt)>({
                let (k, l) = (k.clone(), l.clone().clone());
                let k = k.abs();
                let l = l.abs();
                if l == BigInt::ZERO {
                    (BigInt::ZERO, k)
                } else {
                    let q = k.clone() / l.clone();
                    let r = k % l;
                    (q, r)
                }
            })
        } else {
            {
                let (r, s) = std::convert::identity::<(BigInt, BigInt)>({
                    let (k, l) = (k.clone(), l.clone().clone());
                    let k = k.abs();
                    let l = l.abs();
                    if l == BigInt::ZERO {
                        (BigInt::ZERO, k)
                    } else {
                        let q = k.clone() / l.clone();
                        let r = k % l;
                        (q, r)
                    }
                });
                if s.clone() == BigInt::ZERO {
                    ((-r), BigInt::ZERO)
                } else {
                    ((-r) - BigInt::from_bytes_be(Sign::Plus, &[1]), l.clone() - s)
                }
            }
        }
    } else if l.clone() == BigInt::ZERO {
        (BigInt::ZERO, k)
    } else {
        apsnd((Rc::new(move |a: BigInt| -> BigInt {
            (-a)
        })) as Rc<dyn Fn(BigInt) -> BigInt>, if k.clone() < BigInt::ZERO {
            std::convert::identity::<(BigInt, BigInt)>({
                let (k, l) = (k.clone(), l.clone().clone());
                let k = k.abs();
                let l = l.abs();
                if l == BigInt::ZERO {
                    (BigInt::ZERO, k)
                } else {
                    let q = k.clone() / l.clone();
                    let r = k % l;
                    (q, r)
                }
            })
        } else {
            {
                let (r, s) = std::convert::identity::<(BigInt, BigInt)>({
                    let (k, l) = (k.clone(), l.clone().clone());
                    let k = k.abs();
                    let l = l.abs();
                    if l == BigInt::ZERO {
                        (BigInt::ZERO, k)
                    } else {
                        let q = k.clone() / l.clone();
                        let r = k % l;
                        (q, r)
                    }
                });
                if s.clone() == BigInt::ZERO {
                    ((-r), BigInt::ZERO)
                } else {
                    ((-r) - BigInt::from_bytes_be(Sign::Plus, &[1]), (-l.clone()) - s)
                }
            }
        })
    }
}

