// borrow-optimized by shared parameters
pub fn power<A>(a: &A, n: &BigInt) -> A
where
    A: Clone + Power + 'static
{
    if n.clone() == BigInt::ZERO {
        <A as One>::one()
    } else {
        <A as Times>::times(a.clone(), power(a, &({
            let (m, n) = (n.clone().clone(), <BigInt as One>::one().clone());
            if m <= n.clone() {
                BigInt::ZERO
            } else {
                m - n.clone()
            }
        })))
    }
}

