impl SemiringBitOperations for BigInt {
    fn unset_bit(n: BigInt, k: BigInt) -> BigInt {
        k & !<BigInt as SemiringBitOperations>::push_bit(n, BigInt::from_bytes_be(Sign::Plus, &[1]))
    }
    
    fn take_bit(n: BigInt, k: BigInt) -> BigInt {
        k & <BigInt as SemiringBitOperations>::mask(n)
    }
    
    fn push_bit(n: BigInt, k: BigInt) -> BigInt {
        k * power(&BigInt::from_bytes_be(Sign::Plus, &[2]), &n)
    }
    
    fn flip_bit(n: BigInt, k: BigInt) -> BigInt {
        k ^ <BigInt as SemiringBitOperations>::push_bit(n, BigInt::from_bytes_be(Sign::Plus, &[1]))
    }
    
    fn set_bit(n: BigInt, k: BigInt) -> BigInt {
        k | <BigInt as SemiringBitOperations>::push_bit(n, BigInt::from_bytes_be(Sign::Plus, &[1]))
    }
    
    fn mask(n: BigInt) -> BigInt {
        <BigInt as SemiringBitOperations>::push_bit(n, BigInt::from_bytes_be(Sign::Plus, &[1])) - BigInt::from_bytes_be(Sign::Plus, &[1])
    }
    
    fn drop_bit(n: BigInt, k: BigInt) -> BigInt {
        <BigInt as Divide>::divide(k, power(&BigInt::from_bytes_be(Sign::Plus, &[2]), &n))
    }
    
    fn xor(x0: BigInt, x1: BigInt) -> BigInt {
        {
            let (k, l) = (x0, x1);
            (k ^ l)
        }
    }
    
    fn anda(x0: BigInt, x1: BigInt) -> BigInt {
        {
            let (k, l) = (x0, x1);
            (k & l)
        }
    }
    
    fn ora(x0: BigInt, x1: BigInt) -> BigInt {
        {
            let (k, l) = (x0, x1);
            (k | l)
        }
    }
    
}

