pub fn cmp<A>(x: A, y: A) -> CmpVal
where
    A: Clone + Equal + Linorder + 'static
{
    if <A as Ord>::less(x.clone(), y.clone()) {
        CmpVal::LT
    } else if eq(x, y) {
        CmpVal::EQ
    } else {
        CmpVal::GT
    }
}

pub fn max<A>(a: A, b: A) -> A
where
    A: Clone + Ord + 'static
{
    if <A as Ord>::less_eq(a.clone(), b.clone()) {
        b
    } else {
        a
    }
}

