pub fn nth<A>(x0: &List<A>, n: &BigInt) -> A
where
    A: Clone + 'static
{
    match (x0, n) {
        (List::Cons(x, p0), n) => {
            let xs = p0.as_ref();
            if n.clone() == BigInt::ZERO {
                x.clone()
            } else {
                nth(xs, &({
                    let (m, n) = (n.clone().clone(), <BigInt as One>::one().clone());
                    if m <= n.clone() {
                        BigInt::ZERO
                    } else {
                        m - n.clone()
                    }
                }))
            }
        },
        _ => {
            panic!("non-exhaustive match")
        },
    }
}

