pub fn cmem(a: BigInt) -> BigInt {
    if <BigInt as Equal>::equal(a.clone(), <BigInt as Zero>::zero()) {
        <BigInt as Zero>::zero()
    } else {
        {
            let words = to_word_size(a);
            let square = <BigInt as Times>::times(words.clone(), words.clone());
            let linCoef = <BigInt as Times>::times(words, memory_gas());
            let aa = <BigInt as Divide>::divide(square, quad_coeff_div());
            <BigInt as Plus>::plus(linCoef, aa)
        }
    }
}

pub fn calc_memory_expansion_cost
    (old_size: BigInt, new_size: BigInt) -> CalculationResult {
    if <BigInt as Equal>::equal(new_size.clone(), <BigInt as Zero>::zero()) {
        CalculationResult::CalculationSuccess(<BigInt as Zero>::zero())
    } else if <BigInt as Ord>::less(BigInt::from_bytes_be(Sign::Plus, &[31, 255, 255, 255, 224]), new_size.clone()) {
        CalculationResult::CalcFailureReason(FailureReason::GasUintOverflow)
    } else if <BigInt as Ord>::less_eq(new_size.clone(), old_size.clone()) {
        CalculationResult::CalculationSuccess(<BigInt as Zero>::zero())
    } else {
        {
            let new_words = to_word_size(new_size);
            let _ = <BigInt as Times>::times(new_words.clone(), BigInt::from_bytes_be(Sign::Plus, &[32]));
            let square = <BigInt as Times>::times(new_words.clone(), new_words.clone());
            let lin_coef = <BigInt as Times>::times(new_words, memory_gas());
            let quad_coef = <BigInt as Divide>::divide(square, quad_coeff_div());
            let new_total_fee = <BigInt as Plus>::plus(lin_coef, quad_coef);
            let old_total_fee = cmem(old_size);
            let fee = <BigInt as Minus>::minus(new_total_fee, old_total_fee);
            if <BigInt as Ord>::less(fee.clone(), <BigInt as Zero>::zero()) {
                CalculationResult::CalcFailureReason(FailureReason::GasUintOverflow)
            } else {
                CalculationResult::CalculationSuccess(fee)
            }
        }
    }
}

