// borrow-optimized by shared parameters
pub fn c
    (old_memory_consumption: BigInt, new_memory_consumption1: BigInt, i: &Inst, v: &VariableCtxExt<Unit>, s0: I2rComplexTypeH23D5A13ED65C3783, s1: I2rComplexTypeH23D5A13ED65C3783, s2: I2rComplexTypeH23D5A13ED65C3783, s3: I2rComplexTypeH23D5A13ED65C3783, recipient_empty: bool, orig: I2rComplexTypeH23D5A13ED65C3783, new_val: I2rComplexTypeH23D5A13ED65C3783, remaining_gas: BigInt, net: Network) -> CalculationResult {
    let memu_extra = <BigInt as Minus>::minus(cmem(max(old_memory_consumption.clone(), new_memory_consumption1)), cmem(old_memory_consumption));
    if <BigInt as Ord>::less(memu_extra.clone(), <BigInt as Zero>::zero()) {
        CalculationResult::CalcFailureReason(FailureReason::GasUintOverflow)
    } else {
        third_component_ofc(i, v, s0, s1, s2, s3, recipient_empty, orig, new_val, remaining_gas, net, CalculationResult::CalculationSuccess(memu_extra))
    }
}

// borrow-optimized by shared parameters
pub fn signed_take_bit<A>(n: &BigInt, a: A) -> A
where
    A: Clone + RingBitOperations + 'static
{
    let l = <A as SemiringBitOperations>::take_bit(suc(n), a);
    if <A as SemiringBits>::bita(l.clone(), n.clone()) {
        <A as Plus>::plus(l, <A as SemiringBitOperations>::push_bit(suc(n), <A as Uminus>::uminus(<A as One>::one())))
    } else {
        l
    }
}

pub fn the_signed_int<A>(w: Word<A>) -> BigInt
where
    A: Clone + Len + 'static
{
    signed_take_bit(&({
        let (m, n) = (<A as Len0>::len_of(Itself::Type(PhantomData::<A>)).clone(), suc(&BigInt::ZERO).clone());
        if m <= n {
            BigInt::ZERO
        } else {
            m - n
        }
    }), the_int(w))
}

pub fn word_sless<A>(a: Word<A>, b: Word<A>) -> bool
where
    A: Clone + Len + 'static
{
    <BigInt as Ord>::less(the_signed_int(a), the_signed_int(b))
}

