pub fn vctx_advance_pc
    (c: ConstantCtxExt<Unit>, v: VariableCtxExt<Unit>) -> VariableCtxExt<Unit> {
    vctx_pc_update(({
        let c_cap = c;
        let v_cap = v.clone();
        Rc::new(move |_: BigInt| -> BigInt {
            match vctx_next_instruction(&v_cap, &c_cap) {
                Option::None => {
                    <BigInt as Plus>::plus(vctx_pc(&v_cap), <BigInt as One>::one())
                },
                Option::Some(inst) => {
                    <BigInt as Plus>::plus(vctx_pc(&v_cap), inst_size(inst))
                },
            }
        })
    }) as Rc<dyn Fn(BigInt) -> BigInt>, v)
}

pub fn pc(v: VariableCtxExt<Unit>, c: ConstantCtxExt<Unit>) -> InstructionResult {
    InstructionResult::InstructionContinue(vctx_advance_pc(c, vctx_stack_update(({
        let v_cap = v.clone();
        Rc::new(move |_: I2rComplexTypeHE88F3839A73AA4AA| -> I2rComplexTypeHE88F3839A73AA4AA {
            List::Cons(of_int::<Bit0 <Bit0 <Bit0 <Bit0 <Bit0 <Bit0 <Bit0 <Bit0 <Num1>>>>>>>>>(vctx_pc(&v_cap)), Box::new(vctx_stack(&v_cap)))
        })
    }) as I2rComplexTypeH600B6183C2D3C2AD, v)))
}

