// borrow-optimized by shared parameters
pub fn check_resources
    (v: &VariableCtxExt<Unit>, c: &ConstantCtxExt<Unit>, s: &I2rComplexTypeHE88F3839A73AA4AA, i: &Inst, net: Network) -> CheckResourcesResult {
    {
        let (consumed, produced) = inst_stack_numbers(i.clone());
        let stack_ok = <BigInt as Ord>::less_eq(<BigInt as Minus>::minus(<BigInt as Plus>::plus(int_of_nat(size_list(s)), produced), consumed), BigInt::from_bytes_be(Sign::Plus, &[4, 0]));
        let gas_check = meter_gas(i, v, c, net);
        if stack_ok {
            match gas_check {
                CalculationResult::CalculationSuccess(gas_val) => {
                    CheckResourcesResult::CheckSuccess(<BigInt as Ord>::less_eq(gas_val, vctx_gas(v)))
                },
                CalculationResult::CalcFailureReason(a) => {
                    CheckResourcesResult::CheckFailureReason(a)
                },
            }
        } else {
            CheckResourcesResult::CheckFailureReason(FailureReason::TooLongStack)
        }
    }
}

// borrow-optimized by shared parameters
pub fn program_sem
    (c: ConstantCtxExt<Unit>, fuel_pred: &BigInt, net: Network, pr1: InstructionResult) -> InstructionResult {
    if fuel_pred.clone() == BigInt::ZERO {
        pr1
    } else {
        match pr1.clone() {
            InstructionResult::InstructionContinue(v) => {
                match vctx_next_instruction(&v, &c) {
                    Option::None => {
                        InstructionResult::InstructionToEnvironment(ContractAction::ContractReturn(List::Nil), v, Option::None)
                    },
                    Option::Some(i) => {
                        match check_resources(&v, &c, &vctx_stack(&v), &i, net) {
                            CheckResourcesResult::CheckSuccess(true) => {
                                if <BigInt as Ord>::less_eq(vctx_gas(&v), <BigInt as Zero>::zero()) {
                                    instruction_sem(v, c, i, net)
                                } else {
                                    program_sem(c.clone(), &({
                                        let (m, n) = (fuel_pred.clone().clone(), <BigInt as One>::one().clone());
                                        if m <= n {
                                            BigInt::ZERO
                                        } else {
                                            m - n
                                        }
                                    }), net, instruction_sem(v, c, i, net))
                                }
                            },
                            CheckResourcesResult::CheckSuccess(false) => {
                                instruction_failure_result(v, List::Cons(FailureReason::OutOfGas, Box::new(List::Nil)))
                            },
                            CheckResourcesResult::CheckFailureReason(reason) => {
                                instruction_failure_result(v, List::Cons(reason, Box::new(List::Nil)))
                            },
                        }
                    },
                }
            },
            InstructionResult::InstructionToEnvironment(_, _, _) => {
                pr1
            },
        }
    }
}

// borrow-optimized by shared parameters
pub fn integer_of_hex_char(c: &Char) -> BigInt {
    if BigInt::from_bytes_be(Sign::Plus, &[48]) <= integer_of_char(c) && integer_of_char(c) < BigInt::from_bytes_be(Sign::Plus, &[58]) {
        integer_of_char(c) - BigInt::from_bytes_be(Sign::Plus, &[48])
    } else if BigInt::from_bytes_be(Sign::Plus, &[97]) <= integer_of_char(c) && integer_of_char(c) < BigInt::from_bytes_be(Sign::Plus, &[103]) {
        integer_of_char(c) - BigInt::from_bytes_be(Sign::Plus, &[87])
    } else {
        BigInt::ZERO
    }
}

