pub fn execute_evm_bytecode
    (bytecode: List<Char>, v: &VariableCtxExt<Unit>, c: ConstantCtxExt<Unit>, net: Network, fuel: BigInt) -> InstructionResult {
    let insts = parse_bytes(bytes_of_hex_content(&if ({
        let k = BigInt::from_bytes_be(Sign::Plus, &[2]).clone();
        if k <= BigInt::ZERO {
            BigInt::ZERO
        } else {
            k
        }
    }) <= size_list(&bytecode) && (<Char as Equal>::equal(hd(&bytecode), Char::Char(false, false, false, false, true, true, false, false)) && <Char as Equal>::equal(hd(&tl(bytecode.clone())), Char::Char(false, false, false, true, true, true, true, false))) {
        drop_copy(&({
            let k = BigInt::from_bytes_be(Sign::Plus, &[2]).clone();
            if k <= BigInt::ZERO {
                BigInt::ZERO
            } else {
                k
            }
        }), bytecode.clone())
    } else {
        bytecode.clone()
    }));
    let mut program = program_of_lst(&insts, (Rc::new(move |lst: List<Inst>, eta_arg: BigInt| -> Option<Inst> {
        lookup(program_avl_of_lst(<BigInt as Zero>::zero(), lst), &eta_arg)
    })) as Rc<dyn Fn(List<Inst>, BigInt) -> Option<Inst>>);
    program = program_byte_content_update(({
        Rc::new(move |_: List<Word<Bit0<Bit0<Bit0<Num1>>>>>| -> List<Word<Bit0<Bit0<Bit0<Num1>>>>> {
            bytes_of_hex_content(&bytecode)
        })
    }) as I2rComplexTypeH457684EAB14C662B, program);
    let ca = cctx_program_update(({
        Rc::new(move |_: ProgramExt<Unit>| -> ProgramExt<Unit> {
            program.clone()
        })
    }) as Rc<dyn Fn(ProgramExt<Unit>) -> ProgramExt<Unit>>, c);
    let a = InstructionResult::InstructionContinue(if BigInt::ZERO < fuel.clone() {
        vctx_gas_update(({
            Rc::new(move |_: BigInt| -> BigInt {
                int_of_nat(fuel.clone())
            })
        }) as Rc<dyn Fn(BigInt) -> BigInt>, v.clone())
    } else {
        v.clone()
    });
    program_sem(ca, &nat(vctx_gas(v)), net, a)
}

